package cn.mop.persistence;
import cn.mop.domain.DomainException;
import cn.mop.domain.backup.BackupArchivePayload;
import cn.mop.domain.backup.BackupArchivePayload.Scope;
import cn.mop.persistence.PostgresBackupVersionRepository.*;
import java.sql.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import static cn.mop.persistence.BackupVersionPostgresTest.*;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="MOP_BACKUP_VERSION_INVENTORY_TEST_ENVIRONMENT",matches="dot-backup-version-inventory-disposable")
public class BackupVersionInventoryPostgresTest {
 @org.junit.jupiter.api.Test void isolatedInventoryContract()throws Exception{main(new String[0]);}
 static int inventoryChecks;static void verify(boolean value,String name){if(!value)throw new AssertionError(name);inventoryChecks++;System.out.println("INVENTORY_PASS "+name);}
 static void veto(Runnable action,int status,String name){try{action.run();throw new AssertionError("accepted "+name);}catch(DomainException e){verify(e.status==status&&!e.getMessage().contains("SYNTHETIC_PRIVATE_DETAIL")&&e.getCause()==null,name);}}
 static InventoryAuthorizer inventoryAuthority=(c,a,s)->{if(c.getAutoCommit()||threadOpen.get()!=1)throw new AssertionError("inventory outside owned transaction");if(revoked.get()||!a.tenantId().equals(tenant)||a.permissionVersion()!=1)throw new DomainException(403,"DENIED","SYNTHETIC_PRIVATE_DETAIL");};
 static Fixture additional(UUID asset)throws Exception{
  UUID run=id(),version=id();var acquired=leases().acquire(tenant,asset,id(),"worker",Duration.ofMinutes(5),"inventory-lease");var claim=new PostgresBackupRunRepository.LeaseClaim(acquired.state().requestId(),"worker",acquired.state().fencingToken());runs().queue(tenant,asset,run,id(),"inventory-queue");runs().start(tenant,asset,run,id(),0,claim,"inventory-start");var scope=new Scope(tenant,asset,run,1,version);
  var envelope=crypto.seal(cryptoAccess(),cryptoScope(scope),"SYNTHETIC INVENTORY CONFIGURATION".getBytes(java.nio.charset.StandardCharsets.UTF_8));var payload=BackupArchivePayload.parse(envelope.encoded(),envelope.sha256());objects.put(version,payload.bytes());archive().stage(archiveAccess(),id(),1,payload,"inventory-stage");var event=archive().verifyObject(archiveAccess(),scope,id(),0,REF,"inventory-verify");return new Fixture(scope,payload,claim,event.event().observedAt());
 }
 static void release(Fixture f){var s=leases().current(tenant,f.scope().assetId(),f.lease().requestId()).orElseThrow().state();leases().release(tenant,f.scope().assetId(),s.requestId(),s.owner(),s.fencingToken(),s.version(),REF,"inventory-release");}
 static Map<String,String> snapshot()throws Exception{var result=new TreeMap<String,String>();try(var c=migrator.getConnection();var q=c.createStatement();var rs=q.executeQuery("SELECT tablename FROM pg_tables WHERE schemaname='public' ORDER BY tablename")){var names=new ArrayList<String>();while(rs.next())names.add(rs.getString(1));for(String name:names){if(!name.matches("[a-z_][a-z_0-9]*"))throw new AssertionError("table identifier");try(var s=c.createStatement();var r=s.executeQuery("SELECT count(*)::text||'|'||md5(coalesce(string_agg(row_to_json(t)::text,E'\\n' ORDER BY row_to_json(t)::text),'')) FROM public.\""+name+"\" t")){r.next();result.put(name,r.getString(1));}}}return result;}
 static void fingerprint(UUID version,String hash)throws Exception{try(var c=migrator.getConnection()){c.setAutoCommit(false);try(var q=c.createStatement()){q.execute("ALTER TABLE mop_backup_version_registration DISABLE TRIGGER mop_backup_version_registration_guard");}try(var q=c.prepareStatement("UPDATE mop_backup_version_registration SET command_sha256=? WHERE tenant_id=? AND version_id=?")){q.setString(1,hash);q.setObject(2,tenant);q.setObject(3,version);if(q.executeUpdate()!=1)throw new AssertionError("tamper target missing");}try(var q=c.createStatement()){q.execute("ALTER TABLE mop_backup_version_registration ENABLE TRIGGER mop_backup_version_registration_guard");}c.commit();}}
 public static void main(String[] args)throws Exception{
  if(!"dot-backup-version-inventory-disposable".equals(System.getenv("MOP_BACKUP_VERSION_INVENTORY_TEST_ENVIRONMENT")))throw new IllegalStateException("Explicit disposable inventory gate required");
  BackupVersionPostgresTest.main(new String[0]); // Also rerun the unchanged registration/rollback/concurrency contract.
  var r=repo();var fixture=fixture();UUID asset=fixture.scope().assetId();var scope=new InventoryScope(tenant,asset);var registered=new HashMap<UUID,Registration>();
  for(int i=0;i<16;i++){if(i>0)fixture=additional(asset);var receipt=register(r,fixture,id(),1,REF,REF);registered.put(fixture.scope().versionId(),receipt.registration());release(fixture);}
  var before=snapshot();int objectCalls=objectChecks.get(),completionCalls=completionChecks.get();var first=r.inventory(access(),scope,null,15,inventoryAuthority);
  verify(first.items().size()==15&&first.hasMore()&&first.nextBefore()!=null,"first_page_15_with_explicit_continuation");verify(first.nextBefore().scope().equals(scope)&&first.nextBefore().versionId().equals(first.items().get(14).versionId())&&first.nextBefore().registeredAt().equals(first.items().get(14).registeredAt()),"cursor_pins_scope_and_last_visible_pair");
  var second=r.inventory(access(),scope,first.nextBefore(),15,inventoryAuthority);verify(second.items().size()==1&&!second.hasMore()&&second.nextBefore()==null,"second_page_one_no_invented_total");var all=new ArrayList<InventoryItem>(first.items());all.addAll(second.items());verify(new HashSet<>(all.stream().map(InventoryItem::versionId).toList()).equals(registered.keySet()),"all_registered_versions_once_across_pages");
  var one=r.inventory(access(),scope,null,1,inventoryAuthority);verify(one.items().size()==1&&one.hasMore(),"explicit_page_size_one");verify(r.inventory(access(),scope,null,50,inventoryAuthority).items().size()==16,"maximum_technical_page_size");
  for(var item:all){var source=registered.get(item.versionId());verify(item.assetId().equals(asset)&&item.runId().equals(source.candidate().scope().runId())&&item.encryptedSha256().equals(source.candidate().encryptedSha256())&&item.encryptedBytes()==source.candidate().encryptedBytes()&&item.objectObservedAt().equals(source.candidate().objectObservedAt())&&item.registeredAt().equals(source.registeredAt())&&item.completedRunVersion()==source.completedRunVersion(),"metadata_matches_verified_registration_"+item.versionId());}
  verify(all.stream().allMatch(i->i.registrationAndRunCompletionRecorded()&&!i.currentObjectHealthVerified()&&!i.downloadAuthorized()&&!i.deviceExecutionAuthorized()&&!i.retentionVerified()&&!i.recoveryVerified()),"no_inventory_item_grants_execution_download_or_health");
  Fixture empty=fixture();var emptyScope=new InventoryScope(tenant,empty.scope().assetId());var emptyBefore=snapshot();verify(r.inventory(access(),emptyScope,null,15,inventoryAuthority).items().isEmpty(),"authorized_asset_without_registration_is_empty");verify(snapshot().equals(emptyBefore),"empty_inventory_does_not_register_verified_archive");
  veto(()->r.inventory(access(),scope,null,15,(c,a,s)->{throw new DomainException(403,"DENIED","SYNTHETIC_PRIVATE_DETAIL");}),403,"separate_inventory_authority_required_even_with_per_version_reader");revoked.set(true);veto(()->r.inventory(access(),scope,null,15,inventoryAuthority),403,"revoked_inventory_access_rejected");revoked.set(false);
  var rowDenied=new PostgresBackupVersionRepository(tracked,(c,a,s,o)->{throw new DomainException(403,"DENIED","SYNTHETIC_PRIVATE_DETAIL");},BackupVersionPostgresTest::verifyObject,BackupVersionPostgresTest::verifyCompletion);veto(()->rowDenied.inventory(access(),scope,null,15,inventoryAuthority),403,"asset_enumeration_does_not_replace_per_version_authority");
  UUID lookahead=second.items().get(0).versionId();var lookaheadDenied=new PostgresBackupVersionRepository(tracked,(c,a,s,o)->{authorize(c,a,s,o);if(s.versionId().equals(lookahead))throw new DomainException(403,"DENIED","SYNTHETIC_PRIVATE_DETAIL");},BackupVersionPostgresTest::verifyObject,BackupVersionPostgresTest::verifyCompletion);veto(()->lookaheadDenied.inventory(access(),scope,null,15,inventoryAuthority),403,"lookahead_row_also_authorized_no_partial_result");
  AtomicInteger checks=new AtomicInteger();veto(()->r.inventory(access(),scope,null,15,(c,a,s)->{inventoryAuthority.authorize(c,a,s);if(checks.incrementAndGet()==2)throw new DomainException(403,"REVOKED","SYNTHETIC_PRIVATE_DETAIL");}),403,"final_inventory_authorization_veto_discards_page");
  veto(()->r.inventory(new Access(id(),actor,1),scope,null,15,inventoryAuthority),404,"cross_tenant_cursor_and_asset_hidden");veto(()->r.inventory(access(),emptyScope,first.nextBefore(),15,inventoryAuthority),404,"cursor_cannot_be_reused_for_other_asset");veto(()->r.inventory(access(),new InventoryScope(tenant,id()),null,15,inventoryAuthority),404,"missing_asset_not_reported_as_empty_inventory");
  verify(objectChecks.get()==objectCalls&&completionChecks.get()==completionCalls,"reads_never_call_object_or_completion_write_verifiers");
  // Only the explicit empty fixture writes after the baseline; the following complete read group is fingerprinted separately.
  var stable=snapshot();r.inventory(access(),scope,null,15,inventoryAuthority);r.inventory(access(),scope,first.nextBefore(),15,inventoryAuthority);verify(snapshot().equals(stable),"all_110_tables_unchanged_by_inventory_reads");
  String originalHash=registered.get(lookahead).commandHash();try{fingerprint(lookahead,"0".repeat(64));veto(()->r.inventory(access(),scope,null,15,inventoryAuthority),503,"corrupt_lookahead_fingerprint_rejects_entire_page");}finally{fingerprint(lookahead,originalHash);}verify(snapshot().equals(stable),"disposable_tamper_restored_without_other_table_changes");
  Fixture concurrent=additional(asset);var pool=Executors.newFixedThreadPool(2);var locked=new CountDownLatch(1);var release=new CountDownLatch(1);AtomicInteger authorizationCalls=new AtomicInteger();
  try{Future<InventoryPage> reading=pool.submit(()->r.inventory(access(),scope,null,50,(c,a,s)->{inventoryAuthority.authorize(c,a,s);if(authorizationCalls.incrementAndGet()==2){locked.countDown();try{if(!release.await(3,TimeUnit.SECONDS))throw new AssertionError("test release timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new AssertionError(e);}}}));if(!locked.await(3,TimeUnit.SECONDS))throw new AssertionError("inventory did not hold lock");Future<Receipt> writing=pool.submit(()->register(repo(),concurrent,id(),1,REF,REF));Thread.sleep(100);verify(!writing.isDone(),"registration_waits_for_owned_asset_inventory_lock");release.countDown();verify(reading.get(5,TimeUnit.SECONDS).items().size()==16,"concurrent_new_registration_not_mixed_into_existing_page");writing.get(5,TimeUnit.SECONDS);verify(r.inventory(access(),scope,null,50,inventoryAuthority).items().size()==17,"explicit_new_read_sees_later_registration");}finally{release.countDown();pool.shutdownNow();}
  verify(open.get()==0&&threadOpen.get()==0,"all_inventory_connections_closed");objects.clear();System.out.println("INVENTORY_TOTAL_PASS="+inventoryChecks+" NO_PROVIDER_READS=true NO_DOWNLOADS=true NO_DEVICE_EXECUTION=true");
 }
}
